-- rowstile 0.1.0-dev: authz_governance_records. Generated by rowstile migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- the same policy; what rowstile makes of it changed

-- a migration is one transaction: outside one, nothing below changes anything
SELECT pg_catalog.set_config('authz_ctx.migration', '0f89e67a93d14e15', true);
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '0f89e67a93d14e15' THEN
    PERFORM pg_catalog.set_config('authz_migration.read_only', pg_catalog.current_setting('default_transaction_read_only'), false);
    PERFORM pg_catalog.set_config('default_transaction_read_only', 'on', false);
  END IF;
END $authz_tx$;
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '0f89e67a93d14e15' THEN
    RAISE EXCEPTION 'rowstile: this migration must run in one transaction, and its statements are being committed one by one [AZ615]'
      USING HINT = 'nothing was changed, and this session is read-only until the migration''s last statement; run the file with your migration tool, or with psql -1 -f';
  END IF;
END $authz_tx$;

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF to_regclass('authz.policy_versions') IS NOT NULL THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock = '0f89e67a93d14e15' THEN
    RAISE EXCEPTION 'rowstile: this database already holds what this migration brings (it ran here before, or rowstile dev or push took the database there): don''t run it, tell your migration tool it is applied [AZ607]'
      USING HINT = 'Prisma: prisma migrate resolve --applied <the migration''s folder>. Alembic: alembic stamp head. '
                   'Others, and why: rowstile help AZ607';
  ELSIF v_lock IS DISTINCT FROM '82886bc4e5194a55' THEN
    RAISE EXCEPTION 'rowstile: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      '82886bc4e5194a55', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowstile push or apply since needs the '
                   'migrations from the start (or rowstile apply of the policy the previous migration left) '
                   '(rowstile help AZ607)';
  END IF;
END $authz_guard$;

-- the triggers given to the tables under others: made again below, on what this migration makes
-- @locks ACCESS EXCLUSIVE: the partitions and child tables of the tables rowstile watches
DO $authz_ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT g.tgname, g.tgrelid::regclass AS tbl FROM pg_catalog.pg_trigger g
           JOIN pg_catalog.pg_description d ON d.objoid = g.oid AND d.classoid = 'pg_catalog.pg_trigger'::regclass
           WHERE d.description = 'rowstile: the trigger of the table above, for the rows stored here' LOOP
    EXECUTE pg_catalog.format('DROP TRIGGER %I ON %s', r.tgname, r.tbl);
  END LOOP;
END $authz_ch$;

-- what goes, or is made again
DROP TRIGGER IF EXISTS "authz_folder_col_audit_trunc" ON "app"."folders";
DROP TRIGGER IF EXISTS "authz_message_col_audit_trunc" ON "app"."inbox";
DROP TRIGGER IF EXISTS "authz_note_col_audit_trunc" ON "app"."notes";
DROP TRIGGER IF EXISTS "authz_project_col_audit_trunc" ON "app"."projects";
DROP TRIGGER IF EXISTS "authz_rel_audit_1_trunc" ON "app"."members";
DROP TRIGGER IF EXISTS "authz_rel_audit_2_trunc" ON "app"."project_services";
DROP TRIGGER IF EXISTS "authz_service_col_audit_trunc" ON "app"."services";
DROP TRIGGER IF EXISTS "authz_user_col_audit_trunc" ON "app"."users";

-- The app role must not be the policy's owner, nor a member of it: the rules would not hold for it
DO $ar$
DECLARE v_app name;
BEGIN
  SELECT a.rolname INTO v_app FROM pg_catalog.pg_roles a
  WHERE a.rolname = 'conf_app' AND NOT a.rolsuper AND pg_catalog.pg_has_role(a.oid, CURRENT_USER, 'MEMBER');
  IF v_app IS NOT NULL THEN
    RAISE EXCEPTION 'the app role % is the role that applies the policy (%), or a member of it: the rules would not hold for it [AZ624]', v_app, CURRENT_USER
      USING HINT = 'the policy''s owner skips row-level security, may turn it off, and is believed without a signature: the app connects as a role of its own, which owns nothing of the database';
  END IF;
END $ar$;

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowstile''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

-- Base objects (kept across re-applies)
CREATE SCHEMA IF NOT EXISTS authz;
REVOKE ALL ON SCHEMA authz FROM PUBLIC;

-- Shares people create in the app, for relations marked 'shared' (and custom role assignments)
CREATE TABLE IF NOT EXISTS authz.shares (
  object_type      text        NOT NULL,
  object_id        text        NOT NULL,
  relation         text        NOT NULL,
  subject_type     text        NOT NULL,
  subject_id       text        NOT NULL,
  subject_relation text        NOT NULL DEFAULT '',
  expires_at       timestamptz,
  created_by       text,
  starts_at        timestamptz,
  caveat           text,
  caveat_args      jsonb,
  created_at       timestamptz DEFAULT now(),
  PRIMARY KEY (object_type, object_id, relation, subject_type, subject_id, subject_relation));
CREATE INDEX IF NOT EXISTS shares_by_subject
  ON authz.shares (subject_type, subject_id, subject_relation, object_type, relation);
REVOKE ALL ON authz.shares FROM PUBLIC;
-- A share with anyone names no one: its id is '*' and its relation '', whatever it was made with (authz_int.canon,
-- authz.share). One stored with others takes them; of two that are then one share, the one stored so stays, else
-- the first made
DELETE FROM authz.shares g USING (
  SELECT s.ctid AS row, row_number() OVER (PARTITION BY s.object_type, s.object_id, s.relation
                                           ORDER BY (s.subject_id, s.subject_relation) <> ('*', ''), s.created_at, s.ctid) AS n
  FROM authz.shares s WHERE s.subject_type = 'anyone') d
WHERE g.ctid = d.row AND d.n > 1;
UPDATE authz.shares SET subject_id = '*', subject_relation = ''
WHERE subject_type = 'anyone' AND (subject_id, subject_relation) <> ('*', '');

-- Custom roles: sets of permissions defined as data, assigned like shares ('role:<id>')
CREATE TABLE IF NOT EXISTS authz.roles (
  id          bigserial PRIMARY KEY,
  owner_type  text NOT NULL,
  owner_id    text NOT NULL,
  object_type text NOT NULL,
  name        text NOT NULL,
  created_by  text,
  created_at  timestamptz DEFAULT now(),
  UNIQUE (owner_type, owner_id, object_type, name));
CREATE TABLE IF NOT EXISTS authz.role_permissions (
  role_id    bigint NOT NULL REFERENCES authz.roles ON DELETE CASCADE,
  permission text   NOT NULL,
  PRIMARY KEY (role_id, permission));
REVOKE ALL ON authz.roles, authz.role_permissions FROM PUBLIC;

-- API keys (only a hash of each is kept)
CREATE TABLE IF NOT EXISTS authz.api_keys (
  id           bigserial PRIMARY KEY,
  user_id      text NOT NULL,
  name         text NOT NULL,
  prefix       text NOT NULL,
  hash         text NOT NULL UNIQUE,
  scopes       text NOT NULL DEFAULT '',
  created_at   timestamptz NOT NULL DEFAULT now(),
  expires_at   timestamptz,
  last_used_at timestamptz,
  revoked_at   timestamptz,
  -- whose key: user_id is the principal's id, of this type
  principal_type text NOT NULL DEFAULT 'user');
-- a principal's keys: listed, and deleted with its row
CREATE INDEX IF NOT EXISTS api_keys_by_principal ON authz.api_keys (principal_type, user_id);
-- Settings for the functions (jwt_secret, jwt_issuer, jwt_audience, jwt_user_claim, jwt_type_claim, ...)
CREATE TABLE IF NOT EXISTS authz.settings (key text PRIMARY KEY, value text NOT NULL);
-- The audit trail: every share, role, key, request and impersonation, and relationship changes
CREATE TABLE IF NOT EXISTS authz.audit (
  id               bigserial PRIMARY KEY,
  at               timestamptz NOT NULL DEFAULT clock_timestamp(),
  txid             bigint NOT NULL DEFAULT txid_current(),
  db_role          text,
  user_id          text,
  acting_user      text,
  action           text NOT NULL,
  object_type      text,
  object_id        text,
  relation         text,
  subject_type     text,
  subject_id       text,
  subject_relation text,
  detail           jsonb,
  reason           text);
CREATE INDEX IF NOT EXISTS audit_by_object ON authz.audit (object_type, object_id, at);
REVOKE ALL ON authz.api_keys, authz.settings, authz.audit FROM PUBLIC;

-- For each object with a share that starts or ends later: the next such time, when authz.announce_timed_shares()
-- announces the object (each share's write puts its times in, a run works out the next). A database made before
-- it: the times its shares have after the last run, as that run (timed_shares_to) left them
-- @object table authz.shares_due
DO $due$ BEGIN
  IF to_regclass('authz.shares_due') IS NULL THEN
    CREATE TABLE authz.shares_due (
      object_type text        NOT NULL,
      object_id   text        NOT NULL,
      at          timestamptz NOT NULL,
      PRIMARY KEY (object_type, object_id));
    INSERT INTO authz.shares_due
    SELECT g.object_type, g.object_id, min(v.at) FROM authz.shares g CROSS JOIN LATERAL (VALUES (g.starts_at), (g.expires_at)) v(at)
    WHERE v.at > coalesce((SELECT s.value::timestamptz FROM authz.settings s WHERE s.key = 'timed_shares_to'), '-infinity')
    GROUP BY g.object_type, g.object_id;
  END IF;
END $due$;
CREATE INDEX IF NOT EXISTS shares_due_by_at ON authz.shares_due (at);
REVOKE ALL ON authz.shares_due FROM PUBLIC;
-- (what an earlier authz.announce_timed_shares() kept, the end of its last run, and the indexes it read: no more)
DELETE FROM authz.settings WHERE key = 'timed_shares_to';
DROP INDEX IF EXISTS authz.shares_by_end, authz.shares_by_start;

-- Change feed: objects whose access may have changed, for caches, search indexes, file stores
CREATE TABLE IF NOT EXISTS authz.changes (
  pos         bigserial PRIMARY KEY,
  at          timestamptz NOT NULL DEFAULT clock_timestamp(),
  txid        bigint NOT NULL DEFAULT txid_current(),
  object_type text NOT NULL,
  object_ids  text[] NOT NULL,
  cause       text NOT NULL);
-- the feed's order: by transaction, then position (authz.changes_since)
CREATE INDEX IF NOT EXISTS changes_in_order ON authz.changes (txid, pos);
-- Access requests, approvals, and emergency access
CREATE TABLE IF NOT EXISTS authz.requests (
  id          bigserial PRIMARY KEY,
  object_type text NOT NULL,
  object_id   text NOT NULL,
  relation    text NOT NULL,
  requester   text NOT NULL,
  reason      text,
  duration    interval,
  status      text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'denied', 'cancelled')),
  decided_by  text,
  decided_at  timestamptz,
  note        text,
  created_at  timestamptz NOT NULL DEFAULT now());
-- the pending requests of an object, and a requester's: cancelled when their row goes (decided ones stay, history)
CREATE INDEX IF NOT EXISTS requests_by_object ON authz.requests (object_type, object_id) WHERE status = 'pending';
CREATE INDEX IF NOT EXISTS requests_by_requester ON authz.requests (requester) WHERE status = 'pending';
-- Access reviews: a snapshot of the shares on an object, each kept or revoked by a reviewer
CREATE TABLE IF NOT EXISTS authz.reviews (
  id          bigserial PRIMARY KEY,
  object_type text NOT NULL,
  object_id   text NOT NULL,
  created_by  text,
  created_at  timestamptz NOT NULL DEFAULT now(),
  closes_at   timestamptz,
  closed_at   timestamptz);
CREATE TABLE IF NOT EXISTS authz.review_items (
  review_id        bigint NOT NULL REFERENCES authz.reviews ON DELETE CASCADE,
  item             int    NOT NULL,
  relation         text   NOT NULL,
  subject_type     text   NOT NULL,
  subject_id       text   NOT NULL,
  subject_relation text   NOT NULL,
  expires_at       timestamptz,
  keep             boolean,
  decided_by       text,
  decided_at       timestamptz,
  PRIMARY KEY (review_id, item));
-- The SELECT that masks took away from a role, to give back when they go: the table-wide SELECT, replaced by
-- column privileges (whole), and the SELECT of their own that masked columns had (cols)
CREATE TABLE IF NOT EXISTS authz.masked_tables (
  tbl   text,
  role  text,
  whole boolean NOT NULL,
  cols  text[] NOT NULL,
  PRIMARY KEY (tbl, role));
REVOKE ALL ON authz.changes, authz.requests, authz.reviews, authz.review_items, authz.masked_tables FROM PUBLIC;

-- Every policy the rowstile command applied or removed, with the rowstile version that did it
CREATE TABLE IF NOT EXISTS authz.policy_versions (
  id      bigserial PRIMARY KEY,
  at      timestamptz NOT NULL DEFAULT now(),
  by_role text NOT NULL DEFAULT current_user,
  action  text NOT NULL CHECK (action IN ('apply', 'remove')),
  policy  text,
  files   jsonb NOT NULL DEFAULT '{}',
  version text NOT NULL,
  -- what the migrations' lock file said about this policy (its hash), for the next migration to check
  lock    text);
REVOKE ALL ON authz.policy_versions FROM PUBLIC;

-- Request context for conditions: SET LOCAL authz_ctx.mfa = 'yes', then {authz.ctx('mfa') = 'yes'}. A key
-- not set is NULL. Once a connection has set a key, Postgres reads it as '' in a later transaction that didn't, so
-- '' is NULL too: what an earlier request on a pooled connection set must not show
CREATE OR REPLACE FUNCTION authz.ctx(key text) RETURNS text LANGUAGE sql STABLE AS
  $$ SELECT nullif(current_setting('authz_ctx.' || key, true), '') $$;

-- Link tokens the request presents: SET LOCAL authz_ctx.links = '<token>,<token>'
CREATE OR REPLACE FUNCTION authz.link_hashes() RETURNS text[] LANGUAGE sql STABLE AS $$
  SELECT coalesce(array_agg(encode(sha256(convert_to(btrim(x), 'UTF8')), 'hex')), '{}')
  FROM unnest(string_to_array(nullif(current_setting('authz_ctx.links', true), ''), ',')) x
  WHERE btrim(x) <> '' $$;

-- Inheritance tables kept whose tables have other tables under them since they were computed (a partition
-- attached or detached: no trigger saw those rows) are computed again
DO $stale$
DECLARE r record;
BEGIN
  IF to_regclass('authz_int.trees') IS NULL THEN RETURN; END IF;
  FOR r IN SELECT n.name, n.oids, n.fn FROM (VALUES ('folder__parent__tree', ARRAY[to_regclass('"app"."folders"')::oid]::oid[] || ARRAY(WITH RECURSIVE below(oid) AS (
    SELECT i.inhrelid FROM pg_catalog.pg_inherits i WHERE i.inhparent = ANY (ARRAY[to_regclass('"app"."folders"')::oid]::oid[])
    UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN below b ON i.inhparent = b.oid)
  SELECT b.oid FROM below b ORDER BY b.oid), 'authz_int."folder__parent__tree_rebuild"()')) n(name, oids, fn)
           JOIN authz_int.trees t ON t.name = n.name
           WHERE t.oids IS DISTINCT FROM n.oids AND to_regprocedure(n.fn) IS NOT NULL LOOP
    EXECUTE format('SELECT %s', r.fn);
    UPDATE authz_int.trees SET oids = r.oids WHERE name = r.name;
  END LOOP;
END $stale$;

-- A TRUNCATE empties the tables it names and, without ONLY, the tables under them, and Postgres runs the TRUNCATE
-- triggers of each (those of the audit and the feed too: CHILD_TRIGGERS). They say it once, of the table it was run
-- on: before it, each table is noted unless one above it is (p_key: the trigger function's, of the table and of those
-- under it); after it, a table noted says it, and is noted no more. (A table, not a setting: a session can't set it)
CREATE UNLOGGED TABLE authz_int.truncating (txid bigint NOT NULL, relid oid NOT NULL, key text NOT NULL,
  PRIMARY KEY (txid, relid, key));

CREATE FUNCTION authz_int.truncate_once(p_relid oid, p_key text, p_before boolean) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF NOT p_before THEN
    DELETE FROM authz_int.truncating t WHERE t.txid = txid_current() AND t.relid = p_relid AND t.key = p_key;
    RETURN FOUND;
  END IF;
  IF NOT EXISTS (WITH RECURSIVE up(oid) AS (
                   SELECT i.inhparent FROM pg_inherits i WHERE i.inhrelid = p_relid
                   UNION SELECT i.inhparent FROM pg_inherits i JOIN up ON i.inhrelid = up.oid)
                 SELECT 1 FROM authz_int.truncating t JOIN up ON t.relid = up.oid
                 WHERE t.txid = txid_current() AND t.key = p_key) THEN
    INSERT INTO authz_int.truncating VALUES (txid_current(), p_relid, p_key) ON CONFLICT DO NOTHING;
  END IF;
  RETURN false;
END $f$;

-- A share ends (expires_at) or begins (starts_at) with no write to announce it: this announces the objects whose next
-- share start or end (authz.shares_due, which each share's write keeps) has passed, with the cause share_ended or
-- share_started, and what reads them; then works out each one's next. It keeps no time of its own: a clock set back
-- hides nothing. Schedule it as often as readers should hear of it; until it runs, they don't. Returns the number of
-- shares.
CREATE OR REPLACE FUNCTION authz.announce_timed_shares() RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE
  v_to timestamptz := now();
  v_due authz.shares_due[];
  n bigint;
BEGIN
  -- the objects due, locked (a writer adding a share to one locks it too): this run waits for that writer, and then
  -- reads the shares as it left them, or the writer waits for this run and then puts its share's time in
  v_due := ARRAY(SELECT d FROM authz.shares_due d WHERE d.at <= v_to ORDER BY d.object_type, d.object_id FOR UPDATE);
  PERFORM authz_int.changed(x.object_type, array_agg(x.object_id ORDER BY x.object_id), 'share_ended')
  FROM (SELECT DISTINCT d.object_type, d.object_id FROM unnest(v_due) d
        JOIN authz.shares g ON g.object_type = d.object_type AND g.object_id = d.object_id
        WHERE g.expires_at >= d.at AND g.expires_at <= v_to) x GROUP BY x.object_type;
  PERFORM authz_int.changed(x.object_type, array_agg(x.object_id ORDER BY x.object_id), 'share_started')
  FROM (SELECT DISTINCT d.object_type, d.object_id FROM unnest(v_due) d
        JOIN authz.shares g ON g.object_type = d.object_type AND g.object_id = d.object_id
        WHERE g.starts_at >= d.at AND g.starts_at <= v_to) x GROUP BY x.object_type;
  SELECT count(*) INTO n FROM unnest(v_due) d
  JOIN authz.shares g ON g.object_type = d.object_type AND g.object_id = d.object_id
  WHERE (g.expires_at >= d.at AND g.expires_at <= v_to) OR (g.starts_at >= d.at AND g.starts_at <= v_to);
  -- each one's next start or end, or none
  WITH nx AS MATERIALIZED (
    SELECT d.object_type, d.object_id,
           (SELECT min(v.at) FROM authz.shares g CROSS JOIN LATERAL (VALUES (g.starts_at), (g.expires_at)) v(at)
            WHERE g.object_type = d.object_type AND g.object_id = d.object_id AND v.at > v_to) AS at
    FROM unnest(v_due) d),
  gone AS (DELETE FROM authz.shares_due d USING nx
           WHERE nx.at IS NULL AND d.object_type = nx.object_type AND d.object_id = nx.object_id RETURNING 1)
  UPDATE authz.shares_due d SET at = nx.at FROM nx
  WHERE nx.at IS NOT NULL AND d.object_type = nx.object_type AND d.object_id = nx.object_id;
  RETURN n;
END $f$;

-- shares and role assignments
CREATE OR REPLACE FUNCTION authz_int.on_share() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE r authz.shares;
BEGIN
  r := CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  PERFORM authz_int.audit(CASE TG_OP WHEN 'INSERT' THEN 'share' WHEN 'DELETE' THEN 'unshare' ELSE 'share_changed' END,
    r.object_type, r.object_id, r.relation, r.subject_type,
    CASE WHEN r.subject_type = 'link' THEN '(link)' ELSE r.subject_id END, r.subject_relation,
    jsonb_strip_nulls(jsonb_build_object('expires_at', r.expires_at, 'starts_at', r.starts_at, 'caveat', r.caveat,
                                         'created_by', r.created_by,
                                         -- a change: what the share was (whose, of what, its times)
                                         'was', CASE WHEN TG_OP = 'UPDATE' THEN jsonb_build_object(
                                           'object_type', OLD.object_type, 'object_id', OLD.object_id,
                                           'relation', OLD.relation, 'subject_type', OLD.subject_type,
                                           'subject_id', CASE WHEN OLD.subject_type = 'link' THEN '(link)' ELSE OLD.subject_id END,
                                           'subject_relation', OLD.subject_relation, 'expires_at', OLD.expires_at,
                                           'starts_at', OLD.starts_at, 'caveat', OLD.caveat) END)));
  PERFORM authz_int.changed(r.object_type, ARRAY[r.object_id], 'share');
  -- a share that starts or ends from now on: its object's next such time, for authz.announce_timed_shares() (the
  -- earliest of what the writers put in, each locking the object's row: none is lost; a run works out the next)
  IF TG_OP <> 'DELETE' AND (NEW.starts_at >= now() OR NEW.expires_at >= now()) THEN
    INSERT INTO authz.shares_due AS d
    VALUES (NEW.object_type, NEW.object_id, least(CASE WHEN NEW.starts_at >= now() THEN NEW.starts_at END,
                                                   CASE WHEN NEW.expires_at >= now() THEN NEW.expires_at END))
    ON CONFLICT (object_type, object_id) DO UPDATE SET at = least(d.at, EXCLUDED.at);
  END IF;
  IF TG_OP = 'UPDATE' AND (OLD.object_type, OLD.object_id) IS DISTINCT FROM (NEW.object_type, NEW.object_id) THEN
    PERFORM authz_int.changed(OLD.object_type, ARRAY[OLD.object_id], 'share');
  END IF;
  RETURN NULL;
END $f$;

CREATE OR REPLACE FUNCTION authz_int.on_role() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF TG_TABLE_NAME = 'roles' THEN
    PERFORM authz_int.audit(lower(TG_OP) || '_role', CASE WHEN TG_OP = 'DELETE' THEN OLD.owner_type ELSE NEW.owner_type END,
      CASE WHEN TG_OP = 'DELETE' THEN OLD.owner_id ELSE NEW.owner_id END, NULL, NULL, NULL, NULL,
      to_jsonb(CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END));
  ELSE
    -- (a change: the permission it gave removed, the one it gives added)
    IF TG_OP IN ('DELETE', 'UPDATE') THEN
      PERFORM authz_int.audit('role_permission_removed', NULL, NULL, 'role:' || OLD.role_id, NULL, NULL, NULL,
        jsonb_build_object('permission', OLD.permission));
    END IF;
    IF TG_OP IN ('INSERT', 'UPDATE') THEN
      PERFORM authz_int.audit('role_permission_added', NULL, NULL, 'role:' || NEW.role_id, NULL, NULL, NULL,
        jsonb_build_object('permission', NEW.permission));
    END IF;
  END IF;
  RETURN NULL;
END $f$;

CREATE TRIGGER authz_role_perm_audit_upd AFTER UPDATE ON authz.role_permissions
  FOR EACH ROW WHEN (OLD IS DISTINCT FROM NEW) EXECUTE FUNCTION authz_int.on_role();

-- a role that gives more or less: the objects it is given on (its assignments are shares, 'role:<id>'; a change:
-- the roles it was in and is in)
CREATE OR REPLACE FUNCTION authz_int.on_role_permissions() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    PERFORM authz_int.changed(g.object_type, array_agg(DISTINCT g.object_id), 'role')
    FROM authz.shares g WHERE g.relation IN (SELECT 'role:' || r.role_id FROM role_rows r
                                             UNION SELECT 'role:' || n.role_id FROM new_role_rows n) GROUP BY g.object_type;
  ELSE
    PERFORM authz_int.changed(g.object_type, array_agg(DISTINCT g.object_id), 'role')
    FROM authz.shares g WHERE g.relation IN (SELECT 'role:' || r.role_id FROM role_rows r) GROUP BY g.object_type;
  END IF;
  RETURN NULL;
END $f$;

CREATE TRIGGER authz_role_perm_feed_upd AFTER UPDATE ON authz.role_permissions
  REFERENCING OLD TABLE AS role_rows NEW TABLE AS new_role_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int.on_role_permissions();

